      "fragmentos": [0],
      "seccion": "MD-L000007-L000018"
    },
    {
      "cita_literal_breve": "Los doce contrastes A–L del §12.6 son especificaciones pendientes en esa fuente. Su presencia no permite darlos por ejecutados en este examen, ni convierte comprensión documental en permiso para intervenir en activos.",
      "documento": "CYB-01",
