      "seccion": "MD-L000001-L000006"
    },
    {
      "cita_literal_breve": "Esta sección es una paráfrasis académica del acta, no una transcripción literal ni una declaración de implantación actual.",
      "documento": "CYB-01",
      "fragmentos": [0],
      "seccion": "MD-L000007-L000018"
    },
    {
      "cita_literal_breve": "Las capacidades declaradas, realizadas y comprobadas deben permanecer separadas.",
